INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('22d87175-d697-5ee0-af73-a7f4ce087952', 'faq', 'Goed om te weten', null, '{"items": [{"question": "Kan ik ook reserveren?", "answer": "Bel ons gerust. Online bestellen is voor afhalen, leveren of aan tafel."}, {"question": "Hebben jullie vegetarische gerechten?", "answer": "Ja, die staan met een groen label op de kaart."}, {"question": "Is dit een echte winkel?", "answer": "Nee, dit is een demowinkel van SellQo. Je kan alles uitproberen, ook afrekenen, maar er wordt niets bereid, geleverd of aangerekend."}]}'::jsonb, '{}'::jsonb, 4, true);